# Look up the specific offsets from the backtrace
# libmonosgen-2.0.so frames: 0x222098, 0x222234, 0x19bac0, 0x19bc14
# Let's find what symbols contain these addresses
aarch64-linux-gnu-nm -D libmonosgen-2.0.so 2>/dev/null | sort | awk '
BEGIN { addrs[1]=strtonum("0x222098"); addrs[2]=strtonum("0x222234"); addrs[3]=strtonum("0x19bac0"); addrs[4]=strtonum("0x19bc14") }
/^[0-9a-f]+ [tTwW]/ {
  addr = strtonum("0x"$1)
  name = $3
  for (i=1; i<=4; i++) {
    if (addr <= addrs[i]) { prev[i] = name; prevaddr[i] = addr }
  }
}
END {
  targets[1]="0x222098"; targets[2]="0x222234"; targets[3]="0x19bac0"; targets[4]="0x19bc14"
  for (i=1; i<=4; i++) { print targets[i] " -> " prev[i] " (+" (addrs[i]-prevaddr[i]) ")" }
}'

