arguments.command:
cd /tmp/sv-d7d92d93da2a4dda9fe1fb37bb29ff54/symbols && \
# Better approach: find the closest symbol that is <= target address
for addr in 0x222098 0x222234 0x19bac0 0x19bc14; do
  echo -n "$addr -> "
  aarch64-linux-gnu-nm -D libmonosgen-2.0.so 2>/dev/null | sort | awk -v target="$addr" '
  BEGIN { tgt = strtonum(target); best_name=""; best_addr=0 }
  /^[0-9a-f]+ [tTwW]/ {
    a = strtonum("0x"$1)
    if (a <= tgt && a > best_addr) { best_addr = a; best_name = $3 }
  }
  END { printf "%s+0x%x\n", best_name, tgt - best_addr }'
done

